{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In rats, the disulfonated dye Carmoisine showed no radioactivity in brain at any time, demonstrating that poly-sulfonated anionic dyes do not cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "AZD6370 showed no or low levels of parent compound or metabolites in rat CNS, indicating insufficient blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sulfamide 28 had an exceptionally low brain/plasma exposure ratio in mice and no brain ERK modulation, confirming poor CNS access for polar sulfonamide-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "m-AMSA crossed the blood-brain barrier poorly in rhesus monkeys, with CSF concentrations only 1-3% of systemic concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Radiotracer [123I]53 did not accumulate in rat brain, consistent with low lipophilicity and poor BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "[11C]AZD2423 showed low brain exposure in non-human primates with an SUVpeak of 0.4, indicating inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[11C]AZ10419369 showed low baseline brain uptake in rats that increased 94% after ABC-transporter inhibition, demonstrating efflux-mediated restriction of brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In the first human PET study, [11C]AZ10419369 displayed rapid brain uptake, indicating good CNS access in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 1297 Da polyanionic molecule with six sulfonic acid groups, multiple amide/urea linkages, very high TPSA, and negative logD. Direct evidence from sulfonated dyes and polar sulfonamide/sulfamide-containing molecules consistently shows no or negligible brain penetration. The main contradictory signal, AZ10419369, is a small lipophilic radioligand whose high primate/human brain uptake depends on intrinsic passive permeability that the query lacks; its rodent efflux phenotype actually reinforces the efflux liability. Overall, the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental brain, CSF, or plasma data for the query molecule itself.",
    "No human or primate data for the query.",
    "No evidence for or against active uptake mechanisms, though the large polyanionic structure makes carrier-mediated CNS uptake unlikely.",
    "Transfer scores are moderate (~0.70), and the highest-transfer contradictory evidence comes from a structurally unrelated small lipophilic radioligand."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

